export async function api(path: string, method = 'GET', body?: unknown, signal?: AbortSignal) {
  const response = await fetch('/api/' + path, { method, headers: body instanceof FormData ? {} : body === undefined ? {} : { 'Content-Type': 'application/json' }, body: body === undefined ? undefined : body instanceof FormData ? body : JSON.stringify(body), cache: 'no-store', signal });
  const result = await response.json();
  if (!response.ok) throw new Error(result.error + (result.details ? '：' + result.details.join('；') : ''));
  return result;
}
